import api from '../../utils/api';
import { useRouter } from 'next/navigation';

function RegisterForm() {
    const [formData, setFormData] = useState({
        name: '',
        email: '',
        password: '',
        department: '',
        employeeCode: ''
    });
    const [error, setError] = useState('');
    const [isSubmitting, setIsSubmitting] = useState(false);
    const router = useRouter();

    const handleChange = (e) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setIsSubmitting(true);
        setError('');

        try {
            const res = await api.post('/auth/register', formData);
            // Auto login logic:
            localStorage.setItem('token', res.data.token);
            localStorage.setItem('user', JSON.stringify(res.data.user));
            // Force reload to pick up auth state or we should really update context.
            // For a better UX, redirect to dashboard is enough, the AuthProvider checks token on mount/reload.
            // But since AuthProvider only checks on mount, we might need to force a reload or expose a 'setUser' method.
            // Given the constraints, a window.location.href = '/dashboard' is the most robust "quick fix" to ensure Context re-init.
            window.location.href = '/dashboard';
        } catch (err) {
            setError(err.response?.data?.msg || 'Registration failed');
            setIsSubmitting(false);
        }
    };

    return (
        <div className="flex items-center justify-center min-h-screen py-12 px-4 sm:px-6 lg:px-8">
            <div className="glass-card p-10 w-full max-w-lg space-y-8">
                <div>
                    <h1 className="mt-6 text-center text-3xl font-extrabold text-white">
                        Create your account
                    </h1>
                    <p className="mt-2 text-center text-sm text-gray-300">
                        Or <Link href="/login" className="font-medium text-indigo-400 hover:text-indigo-300">sign in to your existing account</Link>
                    </p>
                </div>
                {error && <div className="bg-red-500/20 text-red-200 p-3 rounded text-sm border border-red-500/50">{error}</div>}

                <form className="mt-8 space-y-6" onSubmit={handleSubmit}>
                    <div className="rounded-md shadow-sm space-y-4">
                        <div>
                            <label className="block text-gray-300 text-xs font-bold mb-1">Full Name</label>
                            <input
                                name="name"
                                type="text"
                                required
                                className="input-field mb-0"
                                placeholder="John Doe"
                                value={formData.name}
                                onChange={handleChange}
                            />
                        </div>
                        <div>
                            <label className="block text-gray-300 text-xs font-bold mb-1">Email address</label>
                            <input
                                name="email"
                                type="email"
                                required
                                className="input-field mb-0"
                                placeholder="john@example.com"
                                value={formData.email}
                                onChange={handleChange}
                            />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-gray-300 text-xs font-bold mb-1">Department</label>
                                <input
                                    name="department"
                                    type="text"
                                    required
                                    className="input-field mb-0"
                                    placeholder="Engineering"
                                    value={formData.department}
                                    onChange={handleChange}
                                />
                            </div>
                            <div>
                                <label className="block text-gray-300 text-xs font-bold mb-1">Employee Code</label>
                                <input
                                    name="employeeCode"
                                    type="text"
                                    required
                                    className="input-field mb-0"
                                    placeholder="EMP-123"
                                    value={formData.employeeCode}
                                    onChange={handleChange}
                                />
                            </div>
                        </div>
                        <div>
                            <label className="block text-gray-300 text-xs font-bold mb-1">Password</label>
                            <input
                                name="password"
                                type="password"
                                required
                                className="input-field mb-0"
                                placeholder="••••••••"
                                value={formData.password}
                                onChange={handleChange}
                            />
                        </div>
                    </div>

                    <div>
                        <button
                            type="submit"
                            disabled={isSubmitting}
                            className={`group relative w-full flex justify-center py-3 px-4 border border-transparent text-sm font-medium rounded-md text-white btn-primary focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 ${isSubmitting ? 'opacity-75' : ''}`}
                        >
                            {isSubmitting ? 'Creating account...' : 'Register'}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
}
